def safe_power(base, exp):
    """
    Calculates base^exp for integers base and exp. 
    Returns None if the result is not a positive integer.
    """
    if base == 0:
        if exp > 0:
            return 0
        elif exp == 0:
            # Conventionally 0^0 might be 1, but let's be strict.
            # If we assume the final product must be an integer, we must handle 0^0.
            # Since primes are >= 2, 0^0=1 is safe if other factors are > 1.
            # For now, we treat 0^0 = 1, which is often used in combinatorics.
            return 1 
        else: # exp < 0
            return None # 0^negative is undefined

    if exp < 0:
        # For base^exp to be an integer, base must be 1 or -1
        if base == 1:
            return 1
        elif base == -1:
            return 1 if exp % 2 == 0 else -1
        else:
            return None # Result is fractional

    # exp >= 0
    try:
        result = base ** exp
        # Since the target must be a POSITIVE prime, we only care about positive results.
        if result > 0:
            return result
        else:
            return None
    except OverflowError:
        return None

