def calculate_p(x, y, z):
    # P = y^x * z^y * x^z
    if x == 0 or y == 0 or z == 0:
        return None

    try:
        # Since x, y, z are integers, P MUST be an integer.
        P_y_x = pow(y, x)
        P_z_y = pow(z, y)
        P_x_z = pow(x, z)

        P = P_y_x * P_z_y * P_x_z

        # Crucial check: P must be positive
        if P <= 0:
            return None

        # Check if P is an integer (which it should be, but checking type guards against calculation errors)
        if isinstance(P, float) and P != int(P):
            return None # Not an integer

        return int(P)
    except Exception:
        # Catch any errors during exponentiation
        return None


