    return n > 1 and sympy.isprime(n)

def evaluate_P(x, y, z):
    """
    Evaluates P = y^x z^y x^z.
    Returns None if P is not an integer, otherwise returns the integer value.
    """
    try:
        # Check for integer result constraints for negative exponents
        if x < 0 and abs(y) != 1:
            return None
        if y < 0 and abs(z) != 1:
            return None
        if z < 0 and abs(x) != 1:
            return None

        # Using math.pow might introduce floating point inaccuracies, stick to built-in operators
        term1 = y**x
        term2 = z**y
        term3 = x**z

        P_float = term1 * term2 * term3

        if P_float != int(P_float):
            return None

        P = int(P_float)
        return P

    except OverflowError:
        return None
    except ZeroDivisionError:
        return None

def search_ordered_good_triples(target_S):
    solutions = []
    max_val = int(target_S**0.5)

    for x in range(-max_val, max_val + 1):
        for y in range(-max_val, max_val + 1):
            z_squared = target_S - x**2 - y**2

            if z_squared < 0:
                continue

            z_float = z_squared**0.5
            if z_float != int(z_float):
                continue

            z_abs = int(z_float)

            for z in [z_abs, -z_abs]:
                triple = (x, y, z)

                # We need to check if this ordered triple is already counted via permutation 
                # if we were iterating over fixed sets, but here we check all unique ordered triples.

                P = evaluate_P(x, y, z)

                if P is not None and is_prime(P):
                    solutions.append(triple)

    return solutions

